import { IconCalendarToday, IconTime } from "@airbus/icons";
import { firefoxOnly, safariOnly, svgColor, svgUri } from "../../helpers";
import { StyleFn } from "..";

export const TimePicker: StyleFn = (theme, mode) => {
  const { size } = theme;
  return {
    root: {
      display: "flex",
      "& $period": {
        width: size.spacing[80],
        marginLeft: size.spacing[16],
        backgroundPosition: `right ${size.spacing[8]} top 50%`,
      },
    },
    period: {},
  }
};

export const DatePicker: StyleFn = (theme, mode) => {
  const { color, elevation, size } = theme;
  const bgSvgColor = color.text.accent.default[mode];
  const backgroundColor = color.surface.elevation[3][mode];

  return {
    root: {},
    inputrange: {
      display: "inline-grid",
      maxWidth: `calc(50% - ${size.spacing[8]})`,
      "&:nth-child(2)": {
        marginLeft: size.spacing[16],
      },
    },
    dialog: {
      position: "absolute",
      backgroundColor,
      zIndex: elevation.zindex.popover,
      boxShadow: elevation.level1,
    },
    // FIXME native date/time pickers support ?
    native: {
      "&[type=date], &[type=time]": {
        position: "relative",
        appearance: "auto",
      },
      // custom calendar indicator
      "&::-webkit-calendar-picker-indicator": {
        color: "transparent",
        background: "none",
      },
      "&:after": {
        content: '""',
        display: "block",
        position: "absolute",
        width: size.spacing[16],
        height: size.spacing[16],
        top: "50%",
        transform: "translateY(-50%)",
        right: size.spacing[12],
        backgroundImage: svgUri(svgColor(IconCalendarToday.data, bgSvgColor)),
        backgroundSize: "100%",
        pointerEvents: "none",
      },
      "&[type=time]:after": {
        backgroundImage: svgUri(svgColor(IconTime.data, bgSvgColor)),
      },
      // safari has no calendar
      ...safariOnly({ "&:after": { display: "none" } }, 14),
      // firefox has a clear button conflicting with indicator
      ...firefoxOnly({ "&:after": { display: "none" } }),
    },
  };
};
